    communityGovde: "DIRECTRICES DE LA COMUNIDAD DE TAMUSO\\n\\nÚltima actualización: 22 de septiembre de 2026\\nVersión: 1.0\\n\\nTamuso está abierto a contenido generado por usuarios (estados, comentarios, mensajes, salas de voz, transmisiones en vivo).\\nSe aplica TOLERANCIA CERO al contenido inapropiado y al abuso.\\n\\n════════════════════════\\n1. EDAD\\n════════════════════════\\nLa plataforma es solo para mayores de 18 años. Está prohibido el contenido o la participación de menores.\\n\\n════════════════════════\\n2. CONTENIDO Y CONDUCTA PROHIBIDOS\\n════════════════════════\\nEstrictamente prohibido:\\n• Acoso, amenazas, acecho, intimidación\\n• Discurso de odio y discriminación\\n• Contenido pornográfico o de explotación sexual\\n• Contenido sexual no consentido\\n• Cualquier contenido relacionado con abuso sexual infantil (CSAM) → sin amnistía\\n• Amenazas de violencia o daño real\\n• Fraude, phishing, spam\\n• Suplantación de identidad\\n• Compartir información personal sin consentimiento (doxxing)\\n• Infracción de derechos de autor\\n• Contenido ilegal\\n• Abuso de la plataforma, bots, exploits\\n\\n════════════════════════\\n3. MODERACIÓN Y 24 HORAS\\n════════════════════════\\n• Los usuarios pueden usar las herramientas Reportar / Bloquear.\\n• Los reportes entran en la cola de moderación; nuestro objetivo es revisarlos en 24 horas.\\n• Ante una infracción, el contenido se elimina; las infracciones repetidas o graves pueden provocar advertencia, suspensión o cierre de la cuenta.\\n\\n════════════════════════\\n4. CONTACTO\\n════════════════════════\\nEn la app: Seguridad → Contáctanos\\nCorreo: support@litxtech.com\\nSoporte en vivo: Ajustes / Seguridad\\n\\nEstas directrices se aplican junto con los Términos de uso y la Política de seguridad infantil.",
